export function packChallenge(machine,arena,seed,rules=DEFAULT_RULES,objective='reactor'){rules=normalizeRules(rules);return {v:VERSION,n:machine.name,p:machine.paint,t:machine.tactic,g:machine.target,d:machine.range,s:machine.stance,a:arena,e:seed>>>0,b:rules.credits??0,q:rules,...(objective&&objective!=='reactor'?{o:objective}:{}),...(machine.front!==undefined?{fr:machine.front}:{}),...(machine.accent?{ac:machine.accent}:{}),...(machine.glow?{gl:machine.glow}:{}),...(machine.pattern?{pt:machine.pattern}:{}),...(machine.number?{no:machine.number}:{}),...(machine.finish?{f:machine.finish}:{}),m:machine.modules.map(m=>{const row=[BY_ID[m.id].index,m.x,m.y,m.r||0];if(m.z||m.u||m.c)row.push(m.z||0);if(m.u||m.c)row.push(m.u||'stock');if(m.c)row.push(m.c);return row;})};}
