 const machine={name:o.n,paint:o.p,tactic:o.t,target:o.g,range:o.d,stance:o.s,modules,...(o.fr!==undefined?{front:o.fr}:{}),...(o.ac?{accent:o.ac}:{}),...(o.gl?{glow:o.gl}:{}),...(o.pt?{pattern:o.pt}:{}),...(o.no?{number:o.no}:{}),...(o.f?{finish:o.f}:{})};
