export function failureLabel(key){return {range:'Out of range',arc:'Outside firing arc',cover:'Blocked by cover',power:'Low energy',heat:'Overheated',target:'Target destroyed',intercept:'Missile intercepted',emp:'EMP disabled'}[key]||key;}
export const ABILITIES={boost:{name:'Boost',key:'1',cost:25,cooldown:14,desc:'Burst of speed \xB7 25 energy'},vent:{name:'Coolant purge',key:'2',cost:20,cooldown:18,desc:'Shed 45 heat; guns pause 1.2s \xB7 20 energy'},brace:{name:'Brace',key:'3',cost:30,cooldown:16,desc:'45% damage reduction for 3s; slower movement \xB7 30 energy'},smoke:{name:'Smoke screen',key:'4',cost:20,cooldown:20,desc:'Break tracking for 5s \xB7 requires Veil launcher'}};
export function rng(seed){let x=seed>>>0||0x9e3779b9;return ()=>{x^=x<<13;x^=x>>>17;x^=x<<5;return (x>>>0)/4294967296;};}
export function world(v,m){const x=(m.x-v.cx)*CELL,y=(m.y-v.cy)*CELL,c=Math.cos(v.a),s=Math.sin(v.a);return {x:v.x+x*c-y*s,y:v.y+x*s+y*c,h:(v.ground||0)+(m.z||0)*LAYER_HEIGHT*CELL};}
export function segmentBox(x1,y1,x2,y2,b,pad=0){let lo=0,hi=1;const dx=x2-x1,dy=y2-y1;for(const [p,q] of [[-dx,x1-b.x+pad],[dx,b.x+b.w+pad-x1],[-dy,y1-b.y+pad],[dy,b.y+b.h+pad-y1]]){if(Math.abs(p)<1e-9){if(q<0)return null;}else{const t=q/p;if(p<0)lo=Math.max(lo,t);else hi=Math.min(hi,t);if(lo>hi)return null;}}return lo;}
